    var map=mountPanMap({container:mapContainer,pause:host.pause,apply:function(a,v){act(a,v,'pan-map');},say:function(text){$('panPieceFeedback').textContent=text;},select:function(index){if(selected===index)return;selected=index;render(view,null,historicalView);}});
