    var controls=node('div',null,'scene-direct-tools');controls.innerHTML='<label for="sceneKitchenTool">Work in the 3D kitchen<select id="sceneKitchenTool"><option value="move">Move ingredients</option><option value="oil">Measure & carry olive oil</option><option value="burner">Turn burner dials</option><option value="weigh">Lift & weigh dry pasta</option><option value="cut">Cut on the board</option><option value="mince">Mince individual garlic cloves</option><option value="dry">Blot produce with cloth</option><option value="stir">Stir the pan</option><option value="sauce-check">Draw & check the sauce trail</option><option value="pot-stir">Separate pasta strands</option><option value="pour">Pour saved water</option><option value="sample">Carry & check a fork sample</option><option value="ladle">Ladle cooking water</option><option value="drain">Lift & drain the pasta pot</option><option value="inspect">Look closely with the food lens</option><option value="turn">Slide & turn with spatula</option><option value="arrange">Move & turn pieces</option><option value="crush">Press softened tomatoes</option><option value="pan">Move pan off heat</option><option value="serve">Serve onto individual plates</option><option value="camera">Move the camera</option></select></label><p id="sceneWeighReading" hidden></p><button id="sceneRecordWeight" type="button" hidden>Record this portion</button><button id="sceneRestoreWeight" type="button" hidden>Restore recorded amount</button><button id="sceneFinishServing" type="button" hidden>Finish serving & review</button><button id="sceneKeyboardTools" type="button">Use keyboard controls</button><p id="sceneToolHelp"></p><p id="sceneActionStatus" tabindex="0" role="status" aria-live="polite" aria-atomic="true"></p>';
