    var descriptions={'sauce-check':'Start at the left side of the sauce pan. Draw steadily right across the sauce, then release. Watch how the track closes and how sauce coats the lifted spoon. An incomplete or cancelled stroke records no check.',turn:'Start on a visible slice. Slide right to tuck the spatula underneath, lift upward, sweep left to turn, then lower and release. A tap or unfinished movement records no turn. Both surfaces keep their cooking history.',oil:'Carry the oil bottle over the graduated cup beside it. Pull down to tilt and fill; lift back or release to stop. Pick up the cup and carry the recipe measure into the sauce pan. Return an overfilled cup to the bottle to remeasure.',sample:'Start inside the pasta pot to take a fork sample. Carry it to the small saucer beside the serving plate. Pull straight down to press, lift back to where the press began, then release. Only a complete movement records its texture.',burner:'Turn around either dial on the front of the stove. Clockwise raises heat; counterclockwise lowers it. Release to apply the preview setting. Escape cancels a turn. The cookware keeps its stored heat after switching off.',weigh:'Lift the pasta packet at the back left over the scale in front of it. When the packet is over the tray, pull down to tilt; pull back up to stop the flow. Release to put it down. To correct an overshoot, drag a small handful from the scale back to the packet. Record the portion before cooking.',serve:'Check the finished dish and turn both burners off. Start on food, pull down to scoop, then lift back to your starting point. Carry the level spoon over a plate, pull down to tip, then release. Scoop from a plate and tip back into the pan to rebalance. Aim for four representative spoonfuls per plate.',mince:'Start on a garlic clove on the small board at the back. Pull straight down through it, lift back to your starting point, then release. Three passes mince a clove. Finish every clove before carrying the garlic bowl to the pan.',drain:'Check a pasta sample and save water first. Drag the pot over the colander at the front left. Once it is in position, pull down to tilt. Lift the pointer to level the pot; release or Escape stops draining. Completed drainage stays removed.',crush:'Start on a tomato piece. Pull down to press, lift back to where you started, then release. Firm pieces keep their shape; softened pieces compress and release a finite amount of juice. Keep some chunks or press twice for a finer sauce.','pot-stir':'Press inside the pasta pot and sweep the spoon through the visible clumps. Cover each group; taps and holding still do not separate strands. Completed separation remains when you release.',dry:'Drag the cloth at the right onto wet areas of the produce and hold. When it fills, hold it over the bowl at the back right to wring it. Completed blotting remains.',ladle:'Carry the ladle over the pot, pull down to dip, then lift back up. Carry it level to the jug, pull down to tip, then release. Each completed carry saves up to 50 mL; hovering, levelling, and unfinished carries change nothing.',move:'Drag the oil bottle, pasta packet, garlic bowl, prepared pieces, or drained pasta in its colander into cookware. Drag empty space to orbit the camera.',cut:'Start on the sample at the width you want. Pull the knife toward the front of the board, then release after a complete stroke.',stir:'Start on the dotted ring. Gather with a full circle in either direction. If pasta is in the pan, keep holding and draw inward to lift and fold it; then release. A full gather and fold records one mix. An unfinished or cancelled motion changes nothing.',pour:'Carry the saved-water jug over the sauce pan. Once positioned, pull straight down to tilt. Lift back to level; move sideways away or release to stop. A level jug adds no water. Completed doses stay in the pan.',inspect:'Start on a visible piece and slide across the pan to magnify its upward face. Release to keep the piece selected. Use the Food lens below to keep and compare views.',arrange:'Drag a piece to another position inside the pan. Tap a piece to turn it over and inspect the other surface.',pan:'Drag the pan by its body or handle onto the trivet at the right, or return it to the burner. Stored heat keeps cooking food as the pan cools.',camera:'Drag to orbit. Scroll or pinch to zoom. Choose a cooking tool to work with objects.'};
    function say(message){$('sceneActionStatus').textContent=message;}
    function refreshScale(){var info=host.scaleInfo(),amount=info.amount;['sceneWeighReading','sceneRecordWeight','sceneRestoreWeight'].forEach(function(id){$(id).hidden=tool!=='weigh';});$('sceneRecordWeight').disabled=info.locked||amount<40||amount===info.recorded;$('sceneRestoreWeight').disabled=info.locked||amount===info.recorded;$('sceneRecordWeight').textContent='Record '+amount+' g portion';$('sceneWeighReading').textContent=info.historical?'Historical portion: '+amount+' g. Weighing is locked.':info.inPot?'Recorded portion: '+info.recorded+' g. This pasta has left the scale.':amount+' g on the tray · '+(800-amount)+' g in the packet · '+info.recorded+' g recorded. Recipe target: '+R.ingredients(host.getState()).pasta+' g.'+(amount>0&&amount<40?' Add at least 40 g before recording.':amount!==info.recorded?' Record the new portion when ready.':'');}
