    function help(){tomatoPanel.render(host.getState(),tool==='crush',host.locked(),lastCrush,null);ladlePanel.render(host.getState(),tool==='ladle',host.locked(),null);platingPanel.render(host.getState(),tool==='serve',host.locked(),null);foldPanel.render(host.getState(),tool==='stir',host.locked(),null);jugPanel.render(host.getState(),tool==='pour',host.locked(),null,lastPour);saucePanel.render(host.getState(),tool==='sauce-check',host.locked());refreshTurn(host.getState());refreshScale();refreshSample(host.getState());refreshOil(host.getState());var portion=R.serving(host.getState());$('sceneFinishServing').hidden=tool!=='serve';$('sceneFinishServing').disabled=host.locked()||!portion.ready||portion.remaining>0; $('sceneToolHelp').textContent=descriptions[tool];canvas.style.cursor=tool==='camera'?'grab':'crosshair';if(shelf)shelf.render(host.getState());}
